function wrap(
    uint256 amount,
    address recipient
) external lock onlyAlchemist returns (uint256) {
    // Transfer the tokens from the message sender.
    SafeERC20.safeTransferFrom(underlyingToken, msg.sender, address(this), amount);

    // Unwrap the WETH into ETH.
    IWETH9(underlyingToken).withdraw(amount);

    // Wrap the ETH into stETH.
    uint256 startingStEthBalance = IERC20(token).balanceOf(address(this));

    IStETH(parentToken).submit{value: amount}(referral);

    uint256 mintedStEth = IERC20(parentToken).balanceOf(address(this)) - startingStEthBalance;

    // Wrap the stETH into wstETH.
    SafeERC20.safeApprove(parentToken, address(token), mintedStEth);
    uint256 mintedWstEth = IWstETH(token).wrap(mintedStEth);

    // Transfer the minted wstETH to the recipient.
    SafeERC20.safeTransfer(token, recipient, mintedWstEth);

    return mintedWstEth;
}

function unwrap(
    uint256 amount,
    address recipient
) external lock onlyAlchemist returns (uint256) {
    // Transfer the tokens from the message sender.
    SafeERC20.safeTransferFrom(token, msg.sender, address(this), amount);

    uint256 balanceBeforeUnderlying = IERC20(underlyingToken).balanceOf(address(this));
    uint256 balanceBeforeYieldToken = IERC20(token).balanceOf(address(this));

    // Vesper withdraw does not accept a recipient argument and does not return withdrawn amount
    IVesperPool(token).withdraw(amount);

    uint256 balanceAfterUnderlying = IERC20(underlyingToken).balanceOf(address(this));
    uint256 balanceAfterYieldToken = IERC20(token).balanceOf(address(this));

    uint256 withdrawn = balanceAfterUnderlying - balanceBeforeUnderlying;

    if (balanceBeforeYieldToken - balanceAfterYieldToken != amount) {
        revert IllegalState("Not all shares were burned");
    }

    // We must transfer to recipient after and use IERC20.balanceOf() for amount
    SafeERC20.safeTransfer(underlyingToken, recipient, withdrawn);

    return withdrawn;
}

function _deposit(uint256 _poolId, uint256 _depositAmount) internal {
  Pool.Data storage _pool = _pools.get(_poolId);
  Stake.Data storage _stake = _stakes[msg.sender][_poolId];

  _pool.totalDeposited = _pool.totalDeposited + _depositAmount;
  _stake.totalDeposited = _stake.totalDeposited + _depositAmount;

  _pool.token.safeTransferFrom(msg.sender, address(this), _depositAmount);

  emit TokensDeposited(msg.sender, _poolId, _depositAmount);
}

function _transferTokensToSelf(address underlyingToken, uint256 collateralInitial) internal override {
    // Convert eth to weth if received eth, otherwise transfer weth
    if (msg.value > 0) {
        if (msg.value != collateralInitial) revert IllegalArgument("msg.value doesn't match collateralInitial");
        IWETH9(wethAddress).deposit{value: msg.value}();
    } else {
        IERC20(underlyingToken).transferFrom(msg.sender, address(this), collateralInitial);
    }
}

