function _sync(
    address yieldToken,
    uint256 amount,
    function(uint256, uint256) internal pure returns (uint256) operation
) internal {
    YieldTokenParams memory yieldTokenParams = _yieldTokens[yieldToken];

    uint256 amountUnderlyingTokens = _convertYieldTokensToUnderlying(yieldToken, amount);
    uint256 updatedActiveBalance   = operation(yieldTokenParams.activeBalance, amount);
    uint256 updatedExpectedValue   = operation(yieldTokenParams.expectedValue, amountUnderlyingTokens);

    _yieldTokens[yieldToken].activeBalance = updatedActiveBalance;
    _yieldTokens[yieldToken].expectedValue = updatedExpectedValue;
}

function _loss(address yieldToken) internal view returns (uint256) {
    YieldTokenParams memory yieldTokenParams = _yieldTokens[yieldToken];

    uint256 amountUnderlyingTokens = _convertYieldTokensToUnderlying(yieldToken, yieldTokenParams.activeBalance);
    uint256 expectedUnderlyingValue = yieldTokenParams.expectedValue;

    return expectedUnderlyingValue > amountUnderlyingTokens
        ? ((expectedUnderlyingValue - amountUnderlyingTokens) * BPS) / expectedUnderlyingValue
        : 0;
}

function _convertYieldTokensToUnderlying(address yieldToken, uint256 amount) internal view returns (uint256) {
    YieldTokenParams storage yieldTokenParams = _yieldTokens[yieldToken];
    ITokenAdapter adapter = ITokenAdapter(yieldTokenParams.adapter);
    return amount * adapter.price() / 10**yieldTokenParams.decimals;
}

function collectFees(
    FeeStructure calldata fees,
    bytes memory packedInfo,
    bytes memory signature
) public payable onlyUtb {
    bytes32 constructedHash = keccak256(
        abi.encodePacked(BANNER, keccak256(packedInfo))
    );
    (bytes32 r, bytes32 s, uint8 v) = splitSignature(signature);
    address recovered = ecrecover(constructedHash, v, r, s);
    require(recovered == signer, "Wrong signature");
    if (fees.feeToken != address(0)) {
        IERC20(fees.feeToken).transferFrom(
            utb,
            address(this),
            fees.feeAmount
        );
    }
}

function swapExactOut(
    SwapParams memory swapParams,
    address receiver,
    address refundAddress
) public payable routerIsSet returns (uint256 amountIn) {
    swapParams = _receiveAndWrapIfNeeded(swapParams);
    IV3SwapRouter.ExactOutputParams memory params = IV3SwapRouter
        .ExactOutputParams({
            path: swapParams.path,
            recipient: address(this),
            //deadline: block.timestamp,
            amountOut: swapParams.amountOut,
            amountInMaximum: swapParams.amountIn
        });

    IERC20(swapParams.tokenIn).approve(uniswap_router, swapParams.amountIn);
    amountIn = IV3SwapRouter(uniswap_router).exactOutput(params);

    // refund sender
    _refundUser(
        refundAddress,
        swapParams.tokenIn,
        params.amountInMaximum - amountIn
    );

    _sendToRecipient(receiver, swapParams.tokenOut, swapParams.amountOut);
}

function swapExactIn(
    SwapParams memory swapParams, // SwapParams is a struct
    address receiver
) public payable routerIsSet returns (uint256 amountOut) {
    swapParams = _receiveAndWrapIfNeeded(swapParams);

    IV3SwapRouter.ExactInputParams memory params = IV3SwapRouter
        .ExactInputParams({
            path: swapParams.path,
            recipient: address(this),
            amountIn: swapParams.amountIn,
            amountOutMinimum: swapParams.amountOut
        });

    IERC20(swapParams.tokenIn).approve(uniswap_router, swapParams.amountIn);
    amountOut = IV3SwapRouter(uniswap_router).exactInput(params);

    _sendToRecipient(receiver, swapParams.tokenOut, amountOut);
}

function execute(
    address target,
    address paymentOperator,
    bytes memory payload,
    address token,
    uint amount,
    address payable refund,
    uint extraNative
) public onlyOwner {
    bool success;
    if (token == address(0)) {
        (success, ) = target.call{value: amount}(payload);
        if (!success) {
            (refund.call{value: amount}(""));
        }
        return;
    }

    uint initBalance = IERC20(token).balanceOf(address(this));

    IERC20(token).transferFrom(msg.sender, address(this), amount);
    IERC20(token).approve(paymentOperator, amount);

    if (extraNative > 0) {
        (success, ) = target.call{value: extraNative}(payload);
        if (!success) {
            (refund.call{value: extraNative}(""));
        }
    } else {
        (success, ) = target.call(payload);
    }

    uint remainingBalance = IERC20(token).balanceOf(address(this)) -
        initBalance;

    if (remainingBalance == 0) {
        return;
    }

    IERC20(token).transfer(refund, remainingBalance);
}

